    [Fact]
    public async Task EchoM365_AcceptsValidUserMessage()
    {
        // Arrange: Create valid UserMessage per TypeSpec
        var message = new UserMessage
        {
            MessageId = "msg_compliance_001",
            UserId = "user_test_123",
            CreatedAt = DateTime.UtcNow,
            Contents = new List<AIContent>
            {
                new TextContent { Text = "Hello EchoM365" }
            }
        };

        var xml = _serializer.Serialize(message);
        var content = new StringContent(xml, Encoding.UTF8, "application/xml");

        // Act: POST to /api/messages
        var response = await _client.PostAsync("/api/messages", content);

        // Assert: 200 OK with AgentMessage
        response.StatusCode.Should().Be(HttpStatusCode.OK);

        var responseXml = await response.Content.ReadAsStringAsync();
        var responseMessage = _serializer.Deserialize(responseXml);

        responseMessage.Should().NotBeNull();
        responseMessage.Should().BeOfType<AgentMessage>();

        var agentMsg = (AgentMessage)responseMessage;
        agentMsg.MessageId.Should().NotBeNullOrEmpty();
        agentMsg.Role.Should().Be(ChatRole.Agent);
        agentMsg.Contents.Should().NotBeEmpty();
    }

