        var responseXml = await response.Content.ReadAsStringAsync();
        return _serializer.Deserialize(responseXml);
    }

    private void ValidateXmlStructure(string xml)
    {
        // Basic XML validation
        xml.Should().NotBeNullOrWhiteSpace();
        xml.Should().Contain("<", "Must be valid XML");

        // Must have root element
        var doc = System.Xml.Linq.XDocument.Parse(xml);
        doc.Root.Should().NotBeNull("Must have root element");

        // Must have message-id attribute
        doc.Root!.Attribute("message-id").Should().NotBeNull(
            "message-id is required per TypeSpec @key annotation");
    }

